import os
import json
from typing import Any, Dict, Optional

from openai import OpenAI


STANDARD_SCHEMA = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "merchant_name": {"type": ["string", "null"]},
        "transaction_date": {"type": ["string", "null"], "description": "ISO 8601 date if available"},
        "currency": {"type": ["string", "null"]},
        "total_amount": {"type": ["number", "null"]},
        "tax_amount": {"type": ["number", "null"]},
        "tip_amount": {"type": ["number", "null"]},
        "payment_method": {"type": ["string", "null"]},
        "expense_category": {"type": ["string", "null"]},
        "receipt_number": {"type": ["string", "null"]},
        "line_items": {
            "type": "array",
            "items": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "description": {"type": ["string", "null"]},
                    "quantity": {"type": ["number", "null"]},
                    "unit_price": {"type": ["number", "null"]},
                    "amount": {"type": ["number", "null"]},
                },
                "required": ["description", "quantity", "unit_price", "amount"],
            },
        },
        "raw_vendor_fields": {"type": "object"},
    },
    "required": [
        "merchant_name",
        "transaction_date",
        "currency",
        "total_amount",
        "tax_amount",
        "tip_amount",
        "payment_method",
        "expense_category",
        "receipt_number",
        "line_items",
        "raw_vendor_fields",
    ],
}


def _get_client() -> OpenAI:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("OPENAI_API_KEY is required")
    return OpenAI(api_key=api_key)


def normalize_expense_fields(extracted_fields: Dict[str, Any]) -> Dict[str, Any]:
    """
    Normalize extracted expense fields into a standard JSON schema.

    Args:
        extracted_fields: Dictionary of already-extracted expense fields from OCR/IDP.

    Returns:
        A dictionary matching the standard schema.
    """
    client = _get_client()

    system_prompt = (
        "You normalize noisy expense/receipt extraction output into a strict canonical schema. "
        "Use null where data is missing. Convert amounts to numbers. "
        "If date is present, prefer ISO 8601 date format YYYY-MM-DD. "
        "Preserve original unusual vendor-specific fields in raw_vendor_fields."
    )

    response = client.responses.create(
        model="gpt-4.1-mini",
        input=[
            {
                "role": "system",
                "content": system_prompt,
            },
            {
                "role": "user",
                "content": json.dumps(
                    {
                        "input_fields": extracted_fields,
                        "output_schema": STANDARD_SCHEMA,
                    },
                    ensure_ascii=False,
                ),
            },
        ],
        response_format={
            "type": "json_schema",
            "json_schema": {
                "name": "standard_expense_schema",
                "schema": STANDARD_SCHEMA,
                "strict": True,
            },
        },
    )

    output_text: Optional[str] = getattr(response, "output_text", None)
    if not output_text:
        try:
            return json.loads(response.output[0].content[0].text)
        except Exception as exc:
            raise ValueError("Failed to parse normalized expense response") from exc

    try:
        return json.loads(output_text)
    except json.JSONDecodeError as exc:
        raise ValueError("Model returned invalid JSON") from exc


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Provide JSON input as a single argument or via stdin.")

    raw = sys.argv[1]
    try:
        input_fields = json.loads(raw)
    except json.JSONDecodeError:
        input_fields = json.loads(sys.stdin.read())

    normalized = normalize_expense_fields(input_fields)
    print(json.dumps(normalized, ensure_ascii=False))
